SINA_SMART["anat3-orbit"] = {"lecture":"anat3-orbit","title":"The orbit: osteology and myology","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat3-orbit:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"untested"},{"id":"anat3-orbit:e8","text":"Inferior oblique is the only extraocular muscle that does not arise at the apex.","topic":"What the lecture asks you to do","sec":1,"importance":"core","highYield":"untested"},{"id":"anat3-orbit:e10","text":"Medial walls parallel, lateral walls about 90 degrees, orbital axes about 45 degrees, visual axes parallel.","topic":"Shape and axes","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-orbit:e0","text":"Seven bones: 3 cranial (frontal, sphenoid, ethmoid) and 4 facial (zygomatic, lacrimal, maxilla, palatine).","topic":"The seven bones","sec":3,"importance":"core","highYield":"untested"},{"id":"anat3-orbit:s4","text":"Describe and explain: Orbital margins (the rim)","topic":"Orbital margins (the rim)","sec":4,"importance":"standard","highYield":"untested"},{"id":"anat3-orbit:e1","text":"Roof: frontal + lesser wing of sphenoid. Floor: maxilla + zygomatic + palatine. Medial: maxilla + lacrimal + ethmoid + sphenoid. Lateral: zygomatic + greater wing of sphenoid.","topic":"Orbital walls","sec":5,"importance":"core","highYield":"untested"},{"id":"anat3-orbit:e2","text":"Lateral wall is the strongest. Medial wall (lamina papyracea) is the thinnest.","topic":"Orbital walls","sec":5,"importance":"core","highYield":"untested"},{"id":"anat3-orbit:e3","text":"The floor of the orbit is the roof of the maxillary sinus.","topic":"Orbital walls","sec":5,"importance":"core","highYield":"untested"},{"id":"anat3-orbit:e7","text":"Supraorbital notch: supraorbital nerve and vessels. Infraorbital foramen: infraorbital nerve and vessels.","topic":"Openings and what passes through them","sec":6,"importance":"core","highYield":"untested"},{"id":"anat3-orbit:e9","text":"LR6 SO4: lateral rectus CN VI, superior oblique CN IV, all the rest CN III.","topic":"Extraocular muscles: attachments and nerve supply","sec":7,"importance":"core","highYield":"untested"},{"id":"anat3-orbit:e4","text":"Optic canal: optic nerve and ophthalmic artery only.","topic":"Pathways worth tracing","sec":8,"importance":"core","highYield":"untested"},{"id":"anat3-orbit:e5","text":"Superior orbital fissure: outside the ring = lacrimal, frontal, trochlear, superior ophthalmic vein. Inside the ring = CN III, CN VI, nasociliary.","topic":"Pathways worth tracing","sec":8,"importance":"core","highYield":"untested"},{"id":"anat3-orbit:e6","text":"Inferior orbital fissure: V2 branches (infraorbital, zygomatic) and infraorbital vessels.","topic":"Pathways worth tracing","sec":8,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"hdayyg":"a","pcdb8q":"a","h9dz85":"a","1twtobh":"a","jeweey":"a","15c4q38":"a","jkpvhw":"a","1vgg9q":"a","xjrpk9":"a","uukpvo":"a","1syp9bz":"a","3wtnpf":"a","o7b1rx":"a","1t1g03a":"a","yxorhe":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat3-orbit:s0":{"s":0,"u":["The orbit is a bony, pyramid-shaped socket that protects the eyeball and holds the muscles, nerves and vessels that serve it.","Its base opens onto the face."],"dp":[{"h":"Tear drainage and the bony canal","t":"The lacrimal fossa is bounded by the anterior lacrimal crest (maxilla) and the posterior lacrimal crest (lacrimal bone). It holds the lacrimal sac and continues as the bony nasolacrimal canal, which opens into the inferior meatus of the nasal cavity. That is how tears from the eye end up in the nose. Sources: StatPearls, Anatomy, Head and Neck, Orbit; Anatomy of Orbit (drtbalu.com)."}]},"anat3-orbit:e8":{"s":1,"u":["Inferior oblique is the only extraocular muscle that does not arise at the apex.","Discuss the attachments of the extraocular muscles and their nerve supply."],"dp":[{"h":"Note","t":"Inferior oblique is the only extraocular muscle that does not arise at the apex: it comes from the front of the orbital floor (maxilla). The superior oblique arises from the sphenoid body, not the ring."}]},"anat3-orbit:e10":{"s":2,"u":["Medial walls parallel, lateral walls about 90 degrees, orbital axes about 45 degrees, visual axes parallel.","Lateral walls of the two orbits meet at about 90 degrees.","Medial walls of the two orbits are roughly parallel."],"dp":[{"h":"Note","t":"Orbital axis ≠ visual axis: orbital axes diverge (about 45° apart, ~22.5° each from the midline); visual axes are parallel . Medial walls are parallel; lateral walls are at about 90°."}]},"anat3-orbit:e0":{"s":3,"u":["Seven bones: 3 cranial (frontal, sphenoid, ethmoid) and 4 facial (zygomatic, lacrimal, maxilla, palatine).","Facial (4): Zygomatic, lacrimal, maxilla, palatine.","Cranial (3): Frontal, sphenoid, ethmoid."],"dp":[{"h":"Note","t":"Seven bones : 3 cranial (frontal, sphenoid, ethmoid) + 4 facial (zygomatic, lacrimal, maxilla, palatine). Know which bones build each wall : roof = frontal + lesser wing; floor = maxilla + zygomatic + palatine; medial = maxilla + lacrimal + ethmoid + sphenoid; lateral = zygomatic + greater wing."}]},"anat3-orbit:s4":{"s":4,"u":["Superior: Formed by = Frontal bone; Worth knowing = Supraorbital notch (or foramen) at the junction of the medial third and lateral two-thirds.","Lateral: Formed by = Zygomatic process of frontal + frontal process of zygomatic; Worth knowing = Where the two bones meet: the frontozygomatic suture."],"dp":[]},"anat3-orbit:e1":{"s":5,"u":["Roof: frontal + lesser wing of sphenoid. Floor: maxilla + zygomatic + palatine. Medial: maxilla + lacrimal + ethmoid + sphenoid. Lateral: zygomatic + greater wing of sphenoid.","Lateral wall: Bones = Zygomatic + greater wing of sphenoid; Key relations and landmarks = The strongest wall..","Roof: Bones = Orbital plate of frontal + lesser wing of sphenoid; Key relations and landmarks = Anterior cranial fossa above."],"dp":[]},"anat3-orbit:e2":{"s":5,"u":["Lateral wall is the strongest. Medial wall (lamina papyracea) is the thinnest.","Lateral wall: Bones = Zygomatic + greater wing of sphenoid; Key relations and landmarks = The strongest wall..","Medial wall: Bones = Frontal process of maxilla + lacrimal + orbital plate of ethmoid + body of sphenoid; Key relations and landmarks = Ethmoid part is the largest and paper-thin (lamina papyracea)."],"dp":[{"h":"Note","t":"Strongest wall = lateral . Thinnest = medial (lamina papyracea of the ethmoid). Commonest blowout = floor (roof of the maxillary sinus)."}]},"anat3-orbit:e3":{"s":5,"u":["The floor of the orbit is the roof of the maxillary sinus.","Floor: Bones = Maxilla (orbital surface) + zygomatic + palatine (orbital process); Key relations and landmarks = Roof of the maxillary sinus."],"dp":[{"h":"Clinical","t":"Floor blowout : fat and inferior rectus herniate into the maxillary sinus → diplopia on upgaze, and numb cheek/upper lip from the infraorbital nerve in the floor. Ethmoid sinusitis spreads through the thin lamina papyracea → orbital cellulitis ."}]},"anat3-orbit:e7":{"s":6,"u":["Supraorbital notch: supraorbital nerve and vessels. Infraorbital foramen: infraorbital nerve and vessels.","Supraorbital notch or foramen: Where = Superior margin; Transmits = Supraorbital nerve and vessels.","Infraorbital foramen: Where = Maxilla, just below the inferior margin; Transmits = Infraorbital nerve and vessels."],"dp":[]},"anat3-orbit:e9":{"s":7,"u":["LR6 SO4: lateral rectus CN VI, superior oblique CN IV, all the rest CN III.","Lateral rectus is CN VI, superior oblique is CN IV, everything else is CN III.","Memory aid for the nerves: LR6 SO4 ."],"dp":[{"h":"Memory aid","t":"LR6 SO4 : lateral rectus = CN VI, superior oblique = CN IV, all other orbital muscles (including levator palpebrae) = CN III. Outside the ring, 'LFT' (lacrimal, frontal, trochlear) plus the superior ophthalmic vein."}]},"anat3-orbit:e4":{"s":8,"u":["Optic canal: optic nerve and ophthalmic artery only.","Optic nerve and ophthalmic artery: travel together through the optic canal into the orbit."],"dp":[{"h":"Orbit size in numbers","t":"The orbit holds roughly 30 mL, of which the eyeball itself takes about 7.5 mL. The long axis of the orbit measures about 44 to 50 mm. The widest diameter of the orbit is not at the rim but about 1 cm behind it, so the orbit is often compared to a pear with its stalk at the optic canal. Source: Bertelli, Orbit chapter (Piccin, 2019, sample pages)."},{"h":"Note","t":"Optic canal carries only two things: CN II and the ophthalmic artery . Everything else of note goes through the fissures."}]},"anat3-orbit:e5":{"s":8,"u":["Superior orbital fissure: outside the ring = lacrimal, frontal, trochlear, superior ophthalmic vein. Inside the ring = CN III, CN VI, nasociliary.","Ophthalmic division (V1): its three branches (lacrimal, frontal, nasociliary) enter through the superior orbital fissure.","CN IV goes through outside the ring."],"dp":[{"h":"How the tendinous ring splits the superior orbital fissure","t":"The common tendinous ring divides the fissure into three sectors: a lateral sector (lacrimal, frontal and trochlear nerves, and the superior ophthalmic vein), a central sector inside the ring (both divisions of CN III, the nasociliary nerve, and CN VI) and an inferior sector (inferior ophthalmic vein). A useful way to remember the outside group is LFT : lacrimal, frontal, trochlear. That helps when you are asked which nerves lie outside the muscle cone. Sources: EyeWiki, Superior Orbital Fissure Syndrome; Neurosurgical Atlas, Superior view of contents of the left orbit."},{"h":"Why a fissure injury shows up as an eye movement problem","t":"Because CN III, IV and VI all cross the superior orbital fissure, damage there can affect several eye movement nerves at once. In one review the abducens nerve was described as the most commonly damaged, because it lies inside the central sector close to the greater wing and has a long course. Source: EyeWiki, Superior Orbital Fissure Syndrome."},{"h":"Note","t":"Superior orbital fissure : inside the tendinous ring = CN III (both divisions), nasociliary, CN VI ; outside the ring = lacrimal, frontal, CN IV, superior ophthalmic vein . Inferior orbital fissure = V2 branches (infraorbital, zygomatic) and infraorbital vessels."}]},"anat3-orbit:e6":{"s":8,"u":["Inferior orbital fissure: V2 branches (infraorbital, zygomatic) and infraorbital vessels.","Maxillary nerve (V2): comes from the pterygopalatine fossa, enters through the inferior orbital fissure, runs in the infraorbital groove and canal as the infraorbital nerve, and exits at the infraorbital foramen onto the cheek.","Ophthalmic division (V1): its three branches (lacrimal, frontal, nasociliary) enter through the superior orbital fissure."],"dp":[]}},"meta":{"hdayyg":{"a":"recall","vg":"anat3-orbit:e10/recall/1"},"pcdb8q":{"a":"recall","vg":"anat3-orbit:e1/recall/1"},"h9dz85":{"a":"recall","vg":"anat3-orbit:e1/recall/1"},"1twtobh":{"a":"recall","vg":"anat3-orbit:e2/recall/1"},"jeweey":{"a":"recall","vg":"anat3-orbit:e3/recall/1"},"15c4q38":{"a":"recall","vg":"anat3-orbit:e4/recall/1"},"jkpvhw":{"a":"recall","vg":"anat3-orbit:e5/recall/1"},"1vgg9q":{"a":"relationship","vg":"anat3-orbit:e1/relationship/1"},"xjrpk9":{"a":"recall","vg":"anat3-orbit:e6/recall/1"},"uukpvo":{"a":"recall","vg":"anat3-orbit:e8/recall/1"},"1syp9bz":{"a":"recall","vg":"anat3-orbit:e9/recall/1"},"3wtnpf":{"a":"recall","vg":"anat3-orbit:e10/recall/2"},"o7b1rx":{"a":"recall","vg":"anat3-orbit:e5/recall/1"},"1t1g03a":{"a":"recall","vg":"anat3-orbit:e8/recall/1"},"yxorhe":{"a":"recall","vg":"anat3-orbit:e3/recall/2"}},"explRev":"f18d5974a10c"};
